WITH ev AS (
  SELECT issue_key, type, occurred_at, recorded_at, payload->>'status' AS status
  FROM events WHERE type IN ('issue.created','issue.status_changed')
),
t AS (SELECT * FROM (VALUES ('A', TIMESTAMP '2017-06-03 09:14'), ('B', TIMESTAMP '2017-07-09 00:31')) v(label, ts)),
joined AS (
  SELECT t.label, e.issue_key, e.occurred_at, e.recorded_at, e.status
  FROM t JOIN ev e ON e.occurred_at <= t.ts AND e.recorded_at <= t.ts
),
-- keep the latest-recorded version of each (issue, occurred_at) as of the instant
corr AS (
  SELECT * FROM (SELECT *, row_number() OVER (PARTITION BY label, issue_key, occurred_at ORDER BY recorded_at DESC) rn FROM joined) WHERE rn = 1
),
cur AS (
  SELECT * FROM (SELECT *, row_number() OVER (PARTITION BY label, issue_key ORDER BY occurred_at DESC) rn FROM corr) WHERE rn = 1
),
hits AS (
  SELECT label, issue_key FROM cur WHERE status IN ('Code Review','Customer Validation','Design','In Progress','To Test')
)
SELECT issue_key FROM hits GROUP BY issue_key HAVING count(DISTINCT label) = 2 ORDER BY issue_key;

WITH st AS (
  SELECT issue_key, type, occurred_at, recorded_at, payload FROM events
  WHERE type IN ('issue.created','issue.status_changed')
),
at1 AS (
  SELECT * FROM st WHERE recorded_at <= TIMESTAMP '2016-04-02 12:47' AND occurred_at <= TIMESTAMP '2016-04-02 12:47'
),
at2 AS (
  SELECT * FROM st WHERE recorded_at <= TIMESTAMP '2016-06-20 02:08' AND occurred_at <= TIMESTAMP '2016-06-20 02:08'
),
-- latest occurred_at, then latest recorded_at for that occurred_at
cur1 AS (
  SELECT issue_key, payload->>'status' AS status FROM (
    SELECT *, row_number() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC) rn FROM at1
  ) WHERE rn = 1
),
cur2 AS (
  SELECT issue_key, payload->>'status' AS status FROM (
    SELECT *, row_number() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC) rn FROM at2
  ) WHERE rn = 1
)
SELECT c1.issue_key, c1.status AS status_0402, c2.status AS status_0620
FROM cur1 c1 JOIN cur2 c2 USING (issue_key)
WHERE c1.status IN ('Confirmed','In Progress','In Review','Stalled')
  AND c2.status IN ('Confirmed','In Progress','In Review','Stalled')
ORDER BY 1;

