WITH known AS (
  SELECT * FROM events WHERE recorded_at <= TIMESTAMP '2021-02-08 20:44' AND issue_key LIKE 'PROJQUAY-%'
),
created AS (
  SELECT issue_key, payload->>'status' AS status, occurred_at FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY issue_key ORDER BY recorded_at DESC) rn FROM known WHERE type='issue.created' AND occurred_at <= TIMESTAMP '2021-02-04 12:48' AND payload->>'project'='PROJQUAY'
  ) WHERE rn=1
),
changes AS (
  SELECT issue_key, occurred_at, payload->>'status' AS status FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY issue_key, occurred_at ORDER BY recorded_at DESC) rn FROM known WHERE type='issue.status_changed' AND occurred_at <= TIMESTAMP '2021-02-04 12:48'
  ) WHERE rn=1
),
latest AS (
  SELECT issue_key, status FROM (
    SELECT c.*, ROW_NUMBER() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC) rn FROM changes c
  ) WHERE rn=1
)
SELECT COUNT(*) AS open_count FROM (
  SELECT cr.issue_key, COALESCE(l.status, cr.status) AS st
  FROM created cr LEFT JOIN latest l USING (issue_key)
) WHERE st = 'Open'

WITH recorded AS (
  SELECT * FROM events WHERE recorded_at <= TIMESTAMP '2021-02-01 15:19'
),
proj AS (
  SELECT DISTINCT issue_key FROM events WHERE type='issue.created' AND payload->>'project'='PROJQUAY'
),
st AS (
  SELECT issue_key, payload->>'status' AS status, occurred_at, recorded_at
  FROM recorded
  WHERE type IN ('issue.status_changed','issue.created') AND payload->>'status' IS NOT NULL
    AND occurred_at <= TIMESTAMP '2021-01-21 16:32'
),
latest AS (
  SELECT issue_key, status FROM (
    SELECT issue_key, status,
           ROW_NUMBER() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC) AS rn
    FROM st
  ) WHERE rn = 1
)
SELECT COUNT(*) FROM latest l JOIN proj p USING (issue_key) WHERE l.status='Resolved';

