WITH rec AS (
  SELECT * FROM events WHERE recorded_at <= TIMESTAMP '2009-07-19 23:23'
),
-- dedupe corrections: latest recorded per (type, issue, occurred_at)
dedup AS (
  SELECT * FROM (
    SELECT *, row_number() OVER (PARTITION BY type, issue_key, occurred_at ORDER BY recorded_at DESC, id DESC) rn
    FROM rec WHERE type IN ('issue.created','issue.status_changed')
  ) WHERE rn = 1
),
valid AS (
  SELECT * FROM dedup WHERE occurred_at <= TIMESTAMP '2009-07-18 14:11'
),
last_status AS (
  SELECT issue_key, payload->>'status' AS status FROM (
    SELECT *, row_number() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC, id DESC) rn
    FROM valid
  ) WHERE rn = 1
)
SELECT count(*) FROM last_status WHERE status = 'In Progress'

