WITH cur AS (
  SELECT * FROM field_versions WHERE field = 'status' AND superseded_at IS NULL
),
a AS (
  SELECT DISTINCT issue_key FROM cur
  WHERE value = 'In Progress' AND valid_from <= TIMESTAMP '2012-05-03 17:42' AND (valid_to IS NULL OR valid_to > TIMESTAMP '2012-05-03 17:42')
),
b AS (
  SELECT DISTINCT issue_key FROM cur
  WHERE value = 'In Progress' AND valid_from <= TIMESTAMP '2012-06-17 04:42' AND (valid_to IS NULL OR valid_to > TIMESTAMP '2012-06-17 04:42')
)
SELECT a.issue_key FROM a JOIN b USING (issue_key) JOIN issues i ON i.key = a.issue_key WHERE i.project = 'RAVE' ORDER BY 1;

WITH ev AS (
  SELECT * FROM events WHERE recorded_at <= TIMESTAMP '2019-05-20 17:43' AND occurred_at <= TIMESTAMP '2019-05-20 17:43'
),
latest AS (
  SELECT issue_key, payload->>'other' AS other, payload->>'relation' AS relation, type,
         ROW_NUMBER() OVER (PARTITION BY issue_key, payload->>'other', payload->>'relation' ORDER BY occurred_at DESC, recorded_at DESC) rn
  FROM ev WHERE type IN ('issue.linked','issue.unlinked')
),
active AS (SELECT issue_key, other, relation FROM latest WHERE rn=1 AND type='issue.linked')
SELECT * FROM active WHERE issue_key IN ('TAJO-744','TAJO-1891') OR other IN ('TAJO-744','TAJO-1891') ORDER BY relation, issue_key, other;

WITH recorded AS (
  SELECT * FROM events WHERE recorded_at <= TIMESTAMP '2013-12-27 07:11' AND occurred_at <= TIMESTAMP '2013-12-24 08:54'
    AND type IN ('issue.created','issue.status_changed')
),
ranked AS (
  SELECT issue_key, occurred_at, recorded_at, id, payload->>'status' AS status,
         ROW_NUMBER() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC, id DESC) AS rn
  FROM recorded
)
SELECT issue_key, occurred_at, recorded_at, status FROM ranked WHERE rn = 1 AND status = 'Patch Available' ORDER BY issue_key;

WITH st AS (
  SELECT issue_key, type, occurred_at, recorded_at, payload->>'status' AS status, payload->>'project' AS project
  FROM events WHERE type IN ('issue.created','issue.status_changed')
),
at1 AS (
  SELECT issue_key, status FROM (
    SELECT *, row_number() OVER (PARTITION BY issue_key, occurred_at ORDER BY recorded_at DESC) rn_rec
    FROM st WHERE occurred_at <= TIMESTAMP '2013-08-25 09:03' AND recorded_at <= TIMESTAMP '2013-08-25 09:03'
  ) WHERE rn_rec=1 QUALIFY row_number() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC)=1
),
at2 AS (
  SELECT issue_key, status FROM (
    SELECT *, row_number() OVER (PARTITION BY issue_key, occurred_at ORDER BY recorded_at DESC) rn_rec
    FROM st WHERE occurred_at <= TIMESTAMP '2013-10-23 09:18' AND recorded_at <= TIMESTAMP '2013-10-23 09:18'
  ) WHERE rn_rec=1 QUALIFY row_number() OVER (PARTITION BY issue_key ORDER BY occurred_at DESC, recorded_at DESC)=1
)
SELECT a.issue_key, a.status AS s1, b.status AS s2 FROM at1 a JOIN at2 b USING (issue_key)
WHERE a.status IN ('In Progress','Patch Available') AND b.status IN ('In Progress','Patch Available')
ORDER BY 1;

